// Golden Quick Insights responses generated by the backend (backend/tests/fixtures/portfolio/insights_*.json, written by
// scripts/write_portfolio_insights_fixtures.py from the home fixture). Orchestrator-owned: never edit a JSON file by
// hand, copy the regenerated set instead. Tests load them through fixture().
const files = import.meta.glob("./*.json", { eager: true, import: "default" }) as Record<string, unknown>;

export const FIXTURE_STATUS = "BACKEND GOLDEN";

export function fixture<T>(name: string): T {
  const key = `./${name}.json`;
  if (!(key in files)) throw new Error(`unknown Quick Insights fixture: ${name}`);
  return structuredClone(files[key]) as T;
}

export const FIXTURE_NAMES = Object.keys(files).map(key => key.slice(2, -5)).sort();
